The invariant is that `size_` stays between 0 and 17, and `head_` identifies the oldest element. Logical element `i` is stored at `(head_ + i) % 17`, so the next insertion goes at `(head_ + size_) % 17`. A full queue rejects pushes without changing state; an empty queue returns no value on pop.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) return false;
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

void require(bool condition) {
    if (!condition) throw std::runtime_error("Test failed");
}

int main() {
    BoundedFIFO queue;
    require(!queue.pop().has_value());

    // Fill and reject overflow without changing the queue.
    for (int i = 0; i < 17; ++i) require(queue.push(i));
    require(queue.size() == 17);
    require(!queue.push(999));
    require(queue.size() == 17);

    // Drain in FIFO order.
    for (int i = 0; i < 17; ++i)
        require(queue.pop() == std::optional<int>{i});
    require(queue.empty());
    require(!queue.pop().has_value());

    // Refill, remove eight, then insert eight across the array boundary.
    for (int i = 17; i < 34; ++i) require(queue.push(i));
    for (int i = 17; i < 25; ++i)
        require(queue.pop() == std::optional<int>{i});
    for (int i = 34; i < 42; ++i) require(queue.push(i));
    require(queue.size() == 17);
    require(!queue.push(999));

    // The wrapped queue must still preserve FIFO order.
    for (int i = 25; i < 42; ++i)
        require(queue.pop() == std::optional<int>{i});
    require(queue.empty());
    require(!queue.pop().has_value());

    std::cout << "All tests passed\n";
}
```

Save as `fifo.cpp`, compile with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo`, and run the resulting executable. This implementation stores integers and assumes single-threaded use.
